"""Stock levels per SKU."""


class OutOfStockError(Exception):
    """Not enough items to remove."""


class Inventory:
    def __init__(self) -> None:
        self._stock: dict[str, int] = {}

    def add(self, sku: str, quantity: int) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._stock[sku] = self._stock.get(sku, 0) + quantity

    def remove(self, sku: str, quantity: int) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        have = self._stock.get(sku, 0)
        if quantity > have:
            raise OutOfStockError(f"{sku}: have {have}, need {quantity}")
        left = have - quantity
        if left:
            self._stock[sku] = left
        else:
            del self._stock[sku]

    def count(self, sku: str) -> int:
        return self._stock.get(sku, 0)

    def skus(self) -> list[str]:
        """SKUs that are in stock, sorted."""
        return sorted(self._stock)
